  "recipes.block-site.summary": "Block access to a domain (social networks, for example) across the whole network.",
  "recipes.block-site.cta": "Go to DNS",
  "recipes.block-site.step1": "Open the *DNS* screen.",
  "recipes.block-site.step2": "In the *block list*, type the domain (`facebook.com`, for example) and add it.",
  "recipes.block-site.step3": "Click *Apply*. The block covers every device that uses this firewall as its DNS.",
  "recipes.block-site.step4": "To allow it again, remove the domain from the list.",
  "recipes.top-talkers.title": "See who is using up the internet",
  "recipes.top-talkers.summary": "Find out which device is using the most bandwidth right now.",
  "recipes.top-talkers.cta": "Go to Hosts",
  "recipes.top-talkers.step1": "Open the *Hosts* screen.",
  "recipes.top-talkers.step2": "At the top, look at the *Top talkers* card — it ranks devices by bandwidth use in real time.",
  "recipes.top-talkers.step3": "The blue bar shows relative usage; to the right, the *download* and *upload* of each one.",
  "recipes.reserve-ip.title": "Give a device a fixed IP",
